import { computed, ref } from 'vue';

const hasDocument = typeof document !== 'undefined';

const isDark = ref<boolean>(
  hasDocument && document.documentElement.classList.contains('gl-dark'),
);

/** 切换/设置暗色：操作 document.documentElement 的 gl-dark class。 */
export function applyToRoot(dark: boolean) {
  isDark.value = dark;
  if (hasDocument) document.documentElement.classList.toggle('gl-dark', dark);
}

export function toggle() {
  applyToRoot(!isDark.value);
}

export function useGitLabTheme() {
  const themeClass = computed<{ 'gl-dark': boolean }>(() => ({ 'gl-dark': isDark.value }));
  return { isDark, toggle, themeClass };
}
